interface Mediator {
    void notify(UIControl sender, String event);
}

abstract class UIControl {
    protected final Mediator mediator;
    protected UIControl(Mediator mediator) { this.mediator = mediator; }
}

class Button extends UIControl {
    private boolean enabled = false;
    Button(Mediator m) { super(m); }
    void click() { mediator.notify(this, "click"); }
    void setEnabled(boolean v) { this.enabled = v; }
    boolean isEnabled() { return enabled; }
}

class Checkbox extends UIControl {
    private boolean checked;
    Checkbox(Mediator m) { super(m); }
    void setChecked(boolean v) { this.checked = v; mediator.notify(this, "check"); }
    boolean isChecked() { return checked; }
}

class TextField extends UIControl {
    private boolean visible = false;
    private String text = "";
    TextField(Mediator m) { super(m); }
    void setText(String t) { this.text = t; mediator.notify(this, "input"); }
    String getText() { return text; }
    void setVisible(boolean v) { this.visible = v; }
}

class ProfileDialog implements Mediator {
    Button submit;
    Checkbox hasDog;
    TextField dogName;

    @Override
    public void notify(UIControl sender, String event) {
        // All cross-object rules live here. Colleagues hold no rules.
        if (event.equals("check")) {
            dogName.setVisible(hasDog.isChecked());
        }
        if (event.equals("check") || event.equals("input")) {
            boolean valid = !hasDog.isChecked() || !dogName.getText().isBlank();
            submit.setEnabled(valid);
        }
        if (event.equals("click") && submit.isEnabled()) {
            save();
        }
    }

    private void save() { /* persist profile */ }
}
